using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Acl;

/// <summary>
///     A field event or clinical intervention applied to an animal.
/// </summary>
/// <param name="OperationId">The identifier generated by the client.</param>
/// <param name="RanchId">The ranch that owns the animal.</param>
/// <param name="CattleId">The animal the operation was applied to.</param>
/// <param name="Type">The kind of operation.</param>
/// <param name="IsClinical">Whether the operation is a clinical intervention.</param>
/// <param name="OccurredAt">The instant the operation happened.</param>
/// <param name="AuthorId">The account that registered the operation.</param>
/// <param name="Product">The administered product, if any.</param>
/// <param name="Dose">The administered dose, if any.</param>
/// <param name="Observation">The free-text observation, if any.</param>
public record LivestockOperationRecord(
    Guid OperationId,
    Guid RanchId,
    Guid CattleId,
    OperationType Type,
    bool IsClinical,
    DateTimeOffset OccurredAt,
    Guid AuthorId,
    string? Product,
    string? Dose,
    string? Observation);
